import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runPhase } from '../case/after/src/runner.mjs';
const expected = { runId: 'r-382', attempt: 3 };
const make = (steps) => ({ run_id: 'r-382', attempt: 3, jobs: [{ steps }] });
const step = (status, conclusion) => ({ status, conclusion });
const checks = [
  ['completed_success_and_skipped', make([step('completed', 'success'), step('completed', 'skipped')]), true],
  ['completed_failure_in_mixed_inventory', make([step('completed', 'success'), step('completed', 'failure')]), false],
  ['completed_cancelled', make([step('completed', 'cancelled')]), false],
  ['completed_null', make([step('completed', null)]), false],
  ['allowlisted_unfinished_nonnull', make([step('queued', 'success')]), false],
  ['nonallowlisted_state_behavior_only', make([step('probe_state_not_in_contract', null)]), false],
  ['wrong_run_id', { ...make([step('completed', 'success')]), run_id: 'r-383' }, false],
  ['wrong_attempt', { ...make([step('completed', 'success')]), attempt: 2 }, false],
  ['empty_jobs', { run_id: 'r-382', attempt: 3, jobs: [] }, false],
  ['empty_steps', make([]), false],
  ['missing_steps', { run_id: 'r-382', attempt: 3, jobs: [{}] }, false],
];
for (const [name, body, admitted] of checks) {
  let reads = 0;
  let calls = 0;
  const result = await runPhase(async () => { reads++; return body; }, expected, async () => { calls++; });
  assert.deepEqual(result, { admitted, commandCalls: admitted ? 1 : 0 });
  assert.equal(reads, 1);
  assert.equal(calls, admitted ? 1 : 0);
  console.log(JSON.stringify({ name, result, reads, calls, assertion: 'PASS' }));
}
const projection = JSON.parse(await readFile(new URL('../case/evidence/observation-01.json', import.meta.url), 'utf8'));
let projectionCalls = 0;
const projectionResult = await runPhase(async () => projection, expected, async () => { projectionCalls++; });
assert.deepEqual(projectionResult, { admitted: false, commandCalls: 0 });
assert.equal(projectionCalls, 0);
console.log(JSON.stringify({ name: 'saved_job_only_projection', result: projectionResult, calls: projectionCalls, assertion: 'PASS', limit: 'Projection lacks archived step payloads and is not the incident response. This result does not identify an improper refusal or its historical cause.' }));
console.log('Provider-recognized unfinished states remain unknown; generated probe_state_not_in_contract is a behavior probe, not a provider-state claim.');

